/bin/bash -lc "cat > index.html <<'EOF'
<"'!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <meta name="theme-color" content="#f6f5ef">
  <meta name="description" content="Join Sam & Priya for their wedding at Hollow Oak Farm in Hudson, New York. June 14, 2027 at 4 PM.">
  <title>Sam & Priya — A day to remember</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,400;0,500;0,600;1,400;1,500&family=DM+Sans:wght@400;450;500;550;600&display=swap" rel="stylesheet">
  <style>
    :root { --paper:#f6f5ef; --card:#fdfcf8; --ink:#343d32; --muted:#7c8075; --olive:#647151; --line:#e2e3d9; --soft:#f0f2e9; }
    * { box-sizing:border-box; }
    body { margin:0; background:var(--paper); color:var(--ink); font-family:'"'DM Sans',sans-serif; font-size:14px; -webkit-font-smoothing:antialiased; }
    button,input,textarea { font:inherit; }
    button,a,input,textarea { -webkit-tap-highlight-color:transparent; }
    button { cursor:pointer; }
    button:focus-visible,a:focus-visible,input:focus-visible,textarea:focus-visible { outline:2px solid var(--olive); outline-offset:4px; }
    .site-header { max-width:1280px; height:108px; margin:auto; padding:0 48px; display:flex; align-items:center; justify-content:space-between; border-bottom:1px solid var(--line); }
    .monogram { font-family:'Cormorant Garamond',Georgia,serif; font-size:31px; font-weight:500; letter-spacing:-1px; text-decoration:none; color:var(--ink); }
    .monogram span { color:var(--olive); font-style:italic; font-size:26px; padding:0 4px; }
    .header-note { color:var(--muted); font-size:10px; letter-spacing:2.4px; text-transform:uppercase; display:flex; align-items:center; gap:15px; }
    .header-note i { width:3px; height:3px; border-radius:50%; background:#9a9e8d; }
    main { max-width:1140px; margin:60px auto 66px; padding:0 28px; display:grid; grid-template-columns:1fr 1fr; gap:88px; align-items:start; }
    .invitation { text-align:center; padding-top:8px; }
    .eyebrow { color:var(--olive); font-size:10px; letter-spacing:2.5px; font-weight:500; text-transform:uppercase; margin:0 0 12px; }
    h1,h2,h3 { font-family:'Cormorant Garamond',Georgia,serif; font-weight:400; }
    h1 { font-size:83px; letter-spacing:-3.6px; line-height:1.08; margin:0 0 13px; white-space:nowrap; }
    h1 em { font-weight:400; color:#7a8566; font-size:76px; }
    .intro { color:var(--muted); font-size:13px; line-height:1.8; margin:0 auto; max-width:340px; }
    .landscape { position:relative; width:368px; max-width:85%; height:263px; margin:31px auto 28px; }
    .landscape::before { content:''; position:absolute; inset:-8px; border:1px solid #cfd3c2; border-radius:190px 190px 4px 4px; pointer-events:none; }
    .landscape img { width:100%; height:100%; object-fit:cover; object-position:center 57%; border-radius:190px 190px 1px 1px; display:block; filter:saturate(.63) brightness(.95); }
    .landscape::after { content:''; position:absolute; inset:0; border-radius:inherit; background:linear-gradient(0deg,#4e563320,transparent); pointer-events:none; }
    .sprig { position:absolute; width:106px; height:153px; right:-48px; bottom:-19px; color:#6b785b; transform:rotate(13deg); filter:drop-shadow(2px 2px 0 var(--paper)); }
    .date { font-family:'Cormorant Garamond',Georgia,serif; font-size:26px; margin:0 0 13px; }
    .venue { font-size:12px; margin:0; line-height:1.9; color:#69715f; }
    .venue strong { color:#4e5946; font-weight:500; }
    .little-divider { width:32px; height:1px; background:#b8bfa9; margin:20px auto 15px; }
    .invitation-note { font-family:'Cormorant Garamond',Georgia,serif; font-style:italic; font-size:19px; color:#7a836c; margin:0; }
    .rsvp-card { background:var(--card); border:1px solid #e3e4db; border-radius:5px; padding:35px 35px 26px; box-shadow:0 6px 25px #3e463004; position:relative; }
    .card-top { display:flex; align-items:center; gap:9px; color:#7e896d; font-size:9px; font-weight:500; letter-spacing:1.8px; text-transform:uppercase; margin-bottom:12px; }
    .card-top svg { width:18px; height:18px; }
    h2 { font-size:43px; letter-spacing:-1px; line-height:1.15; margin:0 0 9px; }
    .card-description { font-size:12px; color:var(--muted); line-height:1.8; margin:0 0 26px; }
    form { display:flex; flex-direction:column; gap:21px; }
    label,.field-label,legend { font-size:11px; font-weight:500; color:#4d5548; margin:0 0 9px; display:block; }
    label .optional { font-weight:400; color:#93978a; margin-left:4px; }
    input[type=text],textarea { width:100%; border:1px solid #dfe2d7; background:#fffefa; border-radius:3px; padding:12px 14px; color:var(--ink); font-size:12px; transition:border-color .2s; }
    input[type=text] { height:45px; }
    input::placeholder,textarea::placeholder { color:#a0a296; opacity:1; }
    input:hover,textarea:hover { border-color:#b4bda8; }
    textarea { resize:vertical; min-height:80px; line-height:1.6; }
    fieldset { padding:0; margin:0; border:0; min-width:0; }
    legend { padding:0; }
    .attendance-options { display:grid; grid-template-columns:1fr 1fr; gap:10px; }
    .attendance-option { position:relative; margin:0; cursor:pointer; }
    .attendance-option input { position:absolute; opacity:0; width:1px; height:1px; }
    .attendance-option .choice { display:flex; align-items:center; gap:8px; height:46px; padding:0 12px; border:1px solid #dfe2d7; border-radius:3px; color:#7c8075; font-size:11px; font-weight:400; transition:background .2s,border-color .2s; }
    .radio-dot { display:grid; place-items:center; width:14px; height:14px; border:1px solid #c8cdbf; border-radius:50%; flex-shrink:0; }
    .radio-dot::after { content:''; width:6px; height:6px; border-radius:50%; background:var(--olive); transform:scale(0); }
    .attendance-option input:checked + .choice { color:#4c5c3d; border-color:#8b9879; background:var(--soft); }
    .attendance-option input:checked + .choice .radio-dot { border-color:#7c8b67; }
    .attendance-option input:checked + .choice .radio-dot::after { transform:scale(1); }
    .attendance-option input:focus-visible + .choice { outline:2px solid var(--olive); outline-offset:3px; }
    .guest-row { display:flex; align-items:center; justify-content:space-between; gap:20px; }
    .guest-row label { margin:0 0 5px; }
    .field-hint { color:#979b8f; font-size:10px; margin:0; line-height:1.5; }
    .stepper { height:40px; border:1px solid #dfe2d7; background:#fffefa; display:flex; border-radius:3px; align-items:center; }
    .stepper button { color:#7c896a; background:none; border:0; height:38px; width:35px; font-size:19px; font-weight:400; }
    .stepper button:disabled { opacity:.35; cursor:default; }
    .stepper input { width:30px; height:24px; text-align:center; padding:0; border:0; background:transparent; color:#4d5548; font-size:12px; appearance:textfield; -moz-appearance:textfield; }
    .stepper input::-webkit-inner-spin-button,.stepper input::-webkit-outer-spin-button { -webkit-appearance:none; margin:0; }
    .submit-button { width:100%; height:46px; border:1px solid var(--olive); border-radius:3px; background:var(--olive); color:#fffefa; font-size:12px; font-weight:450; display:flex; justify-content:center; align-items:center; gap:13px; transition:background .2s,transform .2s; }
    .submit-button:hover { background:#515f40; }
    .submit-button:active { transform:translateY(1px); }
    .submit-button svg { height:15px; width:15px; }
    .form-note { display:flex; justify-content:center; align-items:center; gap:6px; font-size:9px; color:#969c8d; margin:13px 0 0; }
    .form-note svg { width:11px; height:11px; }
    .success { text-align:center; padding:45px 0 35px; min-height:425px; }
    .success-icon { height:60px; width:60px; border:1px solid #c6cfb9; border-radius:50%; display:grid; place-items:center; color:var(--olive); background:var(--soft); margin:0 auto 24px; }
    .success-icon svg { width:25px; }
    .success h3 { font-size:35px; line-height:1.1; margin:0 0 15px; }
    .success p { font-size:13px; color:var(--muted); line-height:1.9; }
    .success .saved-note { font-size:11px; margin:25px 0; }
    .edit-button { border:0; background:transparent; border-bottom:1px solid #a0ab8f; color:var(--olive); padding:5px 0; font-size:12px; }
    [hidden] { display:none"'!important; }
    footer { margin:0 auto; max-width:1184px; border-top:1px solid var(--line); padding:23px 0 26px; display:flex; align-items:center; justify-content:space-between; color:#929888; font-size:10px; }
    .footer-love { display:flex; gap:8px; align-items:center; }
    .footer-love svg { width:12px; height:12px; }
    footer .signature { font-family:'"'Cormorant Garamond',Georgia,serif; font-size:18px; font-style:italic; color:#7b866c; }
    @media(min-width:1500px) { .site-header { margin-top:18px; } main { margin-top:75px; margin-bottom:80px; } }
    @media(max-width:1100px) { main { gap:40px; max-width:990px; } h1 { font-size:72px; } h1 em { font-size:66px; } .rsvp-card { padding:30px 26px 25px; } .landscape { width:320px; height:250px; } footer { margin:0 48px; } }
    @media(max-width:760px) { .site-header { height:82px; padding:0 26px; margin:0 20px; } .header-note { font-size:8px; letter-spacing:1.5px; gap:10px; } main { grid-template-columns:1fr; max-width:540px; gap:40px; margin:35px auto 40px; padding:0 24px; } h1 { font-size:76px; } h1 em { font-size:68px; } .invitation { padding-top:0; } .intro { max-width:320px; } .landscape { width:320px; max-width:82%; height:250px; margin-top:30px; } .sprig { right:-39px; width:90px; } .invitation-note { font-size:18px; } .rsvp-card { padding:30px 25px 25px; } footer { margin:0 24px; gap:20px; padding:20px 0; } footer .signature { font-size:16px; } .footer-love { max-width:165px; line-height:1.7; } }
    @media(max-width:380px) { h1 { font-size:65px; } h1 em { font-size:59px; } .rsvp-card { padding:26px 19px; } .attendance-option .choice { font-size:10px; padding:0 9px; gap:6px; } h2 { font-size:39px; } .header-note { letter-spacing:1px; } }
    @media(prefers-reduced-motion:reduce) { * { transition:none"'!important; } }
  </style>
</head>
<body>
  <header class="site-header">
    <a class="monogram" href="#" aria-label="Sam and Priya home">S<span>&</span>P</a>
    <div class="header-note"><span>June 14, 2027</span><i></i><span>Hudson, NY</span></div>
  </header>
  <main>
    <section class="invitation" aria-labelledby="couple-names">
      <p class="eyebrow">Our favorite day, with our favorite people</p>
      <h1 id="couple-names">Sam <em>&</em> Priya</h1>
      <p class="intro">A little countryside, a lot of love.<br>We’re getting married, and you’re part of the story.</p>
      <div class="landscape">
        <img src="LANDSCAPE_IMAGE" alt="Golden evening light falling over the green countryside" width="736" height="526">
        <svg class="sprig" viewBox="0 0 110 160" fill="none" aria-hidden="true"><path d="M27 155C48 115 60 70 74 9M44 117L18 89M53 91L85 65M63 53L46 29" stroke="currentColor" stroke-width="1.4"/><g fill="currentColor"><ellipse cx="24" cy="96" rx="5" ry="15" transform="rotate(-41 24 96)"/><ellipse cx="38" cy="124" rx="5" ry="15" transform="rotate(-47 38 124)"/><ellipse cx="52" cy="111" rx="5" ry="15" transform="rotate(43 52 111)"/><ellipse cx="66" cy="83" rx="5" ry="16" transform="rotate(47 66 83)"/><ellipse cx="48" cy="65" rx="5" ry="14" transform="rotate(-31 48 65)"/><ellipse cx="73" cy="53" rx="5" ry="15" transform="rotate(35 73 53)"/><ellipse cx="62" cy="35" rx="5" ry="14" transform="rotate(-29 62 35)"/><ellipse cx="74" cy="14" rx="4" ry="13" transform="rotate(16 74 14)"/><ellipse cx="85" cy="65" rx="4" ry="12" transform="rotate(52 85 65)"/></g></svg>
      </div>
      <p class="date">Saturday, June 14, 2027</p>
      <p class="venue"><strong>4:00 PM &nbsp; · &nbsp; Hollow Oak Farm</strong><br>Hudson, New York</p>
      <div class="little-divider"></div>
      <p class="invitation-note">Come for the vows. Stay for the dancing.</p>
    </section>
    <section class="rsvp-card" aria-labelledby="rsvp-title">
      <div class="card-top"><svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M12 20S3.5 14.5 3.5 8.5A4.5 4.5 0 0 1 12 6.4a4.5 4.5 0 0 1 8.5 2.1C20.5 14.5 12 20 12 20Z" stroke="currentColor" stroke-width="1.2"/></svg> A celebration of us, with you</div>
      <h2 id="rsvp-title">Will you join us?</h2>
      <p class="card-description" id="form-description">We’d love to save you a seat.<br>Let us know a little about your plans below.</p>
      <form id="rsvp-form" aria-describedby="form-description">
        <div><label for="guest-name">Your full name</label><input type="text" id="guest-name" name="name" autocomplete="name" placeholder="First and last name" required maxlength="120"></div>
        <fieldset><legend>Will you be celebrating with us?</legend><div class="attendance-options">
          <label class="attendance-option"><input type="radio" name="attendance" value="yes" required checked><span class="choice"><span class="radio-dot"></span>Joyfully accepts</span></label>
          <label class="attendance-option"><input type="radio" name="attendance" value="no" required><span class="choice"><span class="radio-dot"></span>Regretfully declines</span></label>
        </div></fieldset>
        <div class="guest-row" id="guest-field"><div><label for="guest-count">Number of guests</label><p class="field-hint">Including yourself</p></div><div class="stepper"><button type="button" id="decrease" aria-label="Remove one guest" disabled>−</button><input type="number" id="guest-count" name="guests" value="1" min="1" max="10" required aria-label="Number of guests, including yourself"><button type="button" id="increase" aria-label="Add one guest">+</button></div></div>
        <div id="dietary-field"><label for="dietary">Dietary needs <span class="optional">(optional)</span></label><textarea id="dietary" name="dietary" rows="2" maxlength="2000" placeholder="Any allergies or dietary preferences? We’ll do our best to make everyone feel at home."></textarea></div>
        <button class="submit-button" type="submit">Confirm my RSVP <svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M4 12h15m-5-5 5 5-5 5" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round"/></svg></button>
      </form>
      <div id="confirmation" class="success" tabindex="-1" hidden>
        <div class="success-icon"><svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="m5 12 4 4L19 6" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg></div>
        <h3 id="confirmation-title">A seat with your name on it.</h3>
        <p id="confirmation-message"></p>
        <p class="saved-note" id="save-status" role="status"></p>
        <button type="button" class="edit-button" id="edit-response">Edit your response</button>
      </div>
      <p class="form-note" id="local-note"><svg viewBox="0 0 16 16" fill="none" aria-hidden="true"><path d="M4 7V5a4 4 0 0 1 8 0v2M3 7h10v7H3z" stroke="currentColor" stroke-width="1"/></svg>Your response is saved in this browser.</p>
    </section>
  </main>
  <footer><span class="footer-love"><svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M12 20S3 14 3 8.5A4.5 4.5 0 0 1 12 7a4.5 4.5 0 0 1 9 1.5C21 14 12 20 12 20Z" stroke="currentColor" stroke-width="1.3"/></svg>With love, and a little happy anticipation.</span><span class="signature">See you in the countryside.</span></footer>
  <script>
    (() => {
      const form = document.getElementById('"'rsvp-form');
      const name = document.getElementById('guest-name');
      const count = document.getElementById('guest-count');
      const dietary = document.getElementById('dietary');
      const decrease = document.getElementById('decrease');
      const increase = document.getElementById('increase');
      const confirmation = document.getElementById('confirmation');
      const description = document.getElementById('form-description');
      const localNote = document.getElementById('local-note');
      const storageKey = 'sam-priya-wedding-rsvp-2027';
      function updateCounter() {
        decrease.disabled = Number(count.value) <= 1;
        increase.disabled = Number(count.value) >= 10;
      }
      function updateAttendance() {
        const attending = form.elements.attendance.value === 'yes';
        document.getElementById('guest-field').hidden = "'!attending;
        document.getElementById('"'dietary-field').hidden = "'!attending;
        count.disabled = !attending;
        dietary.disabled = !attending;
      }
      decrease.addEventListener('"'click', () => { count.stepDown(); updateCounter(); });
      increase.addEventListener('click', () => { count.stepUp(); updateCounter(); });
      count.addEventListener('input', updateCounter);
      form.querySelectorAll('[name=\"attendance\"]').forEach(radio => radio.addEventListener('change', updateAttendance));
      name.addEventListener('input', () => name.setCustomValidity(''));
      function showConfirmation(response, saved, focus = true) {
        const attending = response.attendance === 'yes';
        document.getElementById('confirmation-title').textContent = attending ? 'A seat with your name on it.' : 'You’ll be there in spirit.';
        document.getElementById('confirmation-message').textContent = attending
          ? "'`Thank you, ${response.name}. Your response is for ${response.guests} ${response.guests === 1 ? '"'guest' : 'guests'}. Here’s to love, laughter, and a little dancing."'`
          : `Thank you for letting us know, ${response.name}. You’ll be missed, and we’ll be thinking of you on our special day.`;
        document.getElementById('"'save-status').textContent = saved ? 'Saved in this browser only. Your response has not been sent to Sam & Priya.' : 'Your response could not be saved in this browser. It has not been sent to Sam & Priya.';
        form.hidden = true;
        description.hidden = true;
        localNote.hidden = true;
        confirmation.hidden = false;
        if (focus) confirmation.focus();
      }
      form.addEventListener('submit', event => {
        event.preventDefault();
        if ("'!name.value.trim()) {
          name.setCustomValidity('"'Please enter your name.');
          name.reportValidity();
          return;
        }
        if ("'!form.reportValidity()) return;
        const response = { name: name.value.trim(), attendance: form.elements.attendance.value, guests: count.disabled ? 0 : Number(count.value), dietary: dietary.disabled ? '"'' : dietary.value.trim() };
        let saved = false;
        try { localStorage.setItem(storageKey, JSON.stringify(response)); saved = true; } catch (error) { /* Private browsing may restrict storage. */ }
        showConfirmation(response, saved);
      });
      document.getElementById('edit-response').addEventListener('click', () => {
        confirmation.hidden = true;
        form.hidden = false;
        description.hidden = false;
        localNote.hidden = false;
        name.focus();
      });
      try {
        const response = JSON.parse(localStorage.getItem(storageKey));
        if (response && typeof response.name === 'string' && response.name.trim() && ['yes','no'].includes(response.attendance) && Number.isInteger(response.guests) && response.guests >= 0 && response.guests <= 10) {
          name.value = response.name;
          form.elements.attendance.value = response.attendance;
          count.value = Math.max(1, response.guests);
          dietary.value = typeof response.dietary === 'string' ? response.dietary : '';
          updateAttendance();
          updateCounter();
          showConfirmation(response, true, false);
        }
      } catch (error) { /* The form remains usable without saved data. */ }
    })();
  </script>
</body>
</html>
EOF
